# ------------------------------------------------------------------ numerics

def _canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), allow_nan=False).encode()


def rng_for(seed, identity):
    """Same identity-keyed construction as the workflow provider's noise streams."""
    digest = hashlib.sha256(f"{seed}:{identity}".encode()).digest()
    return np.random.default_rng(int.from_bytes(digest[:8], "big"))


def sig(x):
    return 1.0 / (1.0 + math.exp(-x))


def logit(p):
    return math.log(p / (1.0 - p))


def arrhenius(e_kj_mol, t_c, ref_c=600.0):
    return math.exp(-e_kj_mol * 1000.0 / R * (1.0 / (t_c + 273.15) - 1.0 / (ref_c + 273.15)))


def _number(value, name, low=None, high=None):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError(f"{name} must be a finite number")
    if (low is not None and value < low) or (high is not None and value > high):
        raise ValueError(f"{name} {value:g} outside the conditional support envelope [{low:g}, {high:g}]")
    return float(value)


# ------------------------------------------------------------------ densification

def density_on_heating(peak_c, ramp, hold_s, pressure_mpa, dens):
    dose = thermal_dose(peak_c, ramp, hold_s, dens["Q_kj_mol"], cooling_rate_c_min=SPS_COOLING_C_MIN)
    k = math.exp(dens["log_k"]) * (pressure_mpa / 50.0) * (ramp / 100.0) ** dens["gamma_ramp"]
    return dens["rho_inf"] - (dens["rho_inf"] - dens["rho0"]) * math.exp(-k * dose)


def density(rt, w):
    dens = w["cal"]["density"]
    rho = density_on_heating(rt["peak_c"], rt["ramp"], rt["hold_s"], rt["pressure_mpa"], dens)
    # hidden, bounded offset where the closure is weakly identified (below 850 C)
    rho += w.get("rho_offset_800", 0.0) * max(0.0, (850.0 - rt["peak_c"]) / 50.0)
    if rt["schedule"] == "on_dwell":
        rho -= w["drho_dwell"]
    elif rt["schedule"] == "on_cooling":
        rho -= w["cal"]["drho_E"] * math.exp((750.0 - rt["t_full_c"]) / w["theta_rho"])
    return rho


# ------------------------------------------------------------------ demagnetization curve

def n_from_squareness(s):
    return math.log(0.1) / math.log(s)


def squareness_from_n(n):
    return 0.1 ** (1.0 / n)


def bhmax(br, hci, n, points=4000):
    """(BH)max in MGOe for J(H) = Br (1 - (|H|/Hci)^n); CGS, B = H + J, kOe x kG = MGOe."""
    x = np.linspace(1e-4, 1.0, points)
    h = hci * x
    j = br * (1.0 - x ** n)
    b = j - h
    return float(np.max(np.where(b > 0, h * b, 0.0)))


def demag_vertices(br, hci, n, count=111, x_max=1.1):
    """Explicit J(H) vertices from H = 0 through slightly beyond Hci."""
    xs = [x_max * i / (count - 1) for i in range(count)]
    return [0.0 if x == 0 else -hci * x for x in xs], [br * (1.0 - x ** n) for x in xs]


# ------------------------------------------------------------------ latent state

def anneal_effects(steps, w, lot):
    cal = w["cal"]
    m_l = lot["m_L"]
    dz, r_br, r_n, had_high = 0.0, 1.0, 1.0, False
    for t_c, hold in steps:
        g = (1 - math.exp(-hold / w["tau_anneal_s"])) / (1 - math.exp(-ANNEAL_REF_S / w["tau_anneal_s"]))
        if t_c >= HIGH_STEP_MIN_C:
            s1 = sig((t_c - w["T1_50"]) / 25.0) / sig((900.0 - w["T1_50"]) / 25.0)
            dz += cal["A1"] * s1 * g
            frac = max(0.0, (t_c - 600.0) / 300.0)
            r_br *= 1.0 - (1.0 - cal["r1_900"]) * m_l * frac ** w["q_L"] * g
            r_n *= 1.0 - (1.0 - cal["n1_ratio"]) * m_l * frac ** w["q_S"] * g
            had_high = True
        else:
            b2 = (math.exp(-(t_c - w["T2_star"]) ** 2 / (2 * w["w2"] ** 2))
                  / math.exp(-(520.0 - w["T2_star"]) ** 2 / (2 * w["w2"] ** 2)))
            solo = 1.0 if had_high else w["kappa_solo"]
            dz += cal["A2"] * b2 * g * solo
            r_br *= 1.0 + (cal["r2_520"] - 1.0) * b2 * g * solo
            # loop shape follows the anchored direction whatever the sign of a low-T-only step
            r_n *= 1.0 + (cal["n2_ratio"] - 1.0) * b2 * g * abs(solo)
    return dz, r_br, r_n


def latent_state(rt, w, lot, batch_u=0.0, body_v=0.0, rho_eps=0.0):
    """Noise-free latent magnetic state plus supplied batch and body random effects.

    rt: route {degas_c, degas_s, peak_c, ramp, hold_s, pressure_mpa, schedule, t_full_c,
    anneal: [(temperature_c, hold_s), ...]}; w: hidden parameters plus inverted ``cal``;
    lot: {h_lot, o_lot, m_L, n_lot}.
    """
    cal = w["cal"]
    k600 = w["kappa"] / 600.0
    t_dg = rt["degas_s"]
    h = lot["h_lot"] * math.exp(batch_u) * (
        math.exp(-k600 * arrhenius(w["E_dg"], rt["degas_c"]) * t_dg) if t_dg > 0 else 1.0)
    o = lot["o_lot"] * (t_dg / 600.0) * arrhenius(w["E_ox"], rt["degas_c"]) if t_dg > 0 else 0.0
    lam = (cal["dCD"] + w["Omega"]) / (1.0 - math.exp(-w["kappa"]))
    z = cal["zC"] + lam * (1.0 - h) - w["Omega"] * o
    if rt["schedule"] == "on_dwell":
        z += w["phi_dwell"] * cal["dDE"]
    elif rt["schedule"] == "on_cooling":
        def bell(t):
            return math.exp(-(t - w["T_on_star"]) ** 2 / (2 * w["w_on"] ** 2))
        z += cal["dDE"] * bell(rt["t_full_c"]) / bell(750.0)
    z -= w["d_liq"] * ((1 - sig((rt["peak_c"] - w["T_liq"]) / 15.0)) - (1 - sig((850.0 - w["T_liq"]) / 15.0)))
    grain_nm = w["grain_powder_nm"] * (1.0 + 0.15 * sig((rt["peak_c"] - 870.0) / 20.0))
    grain_ref = w["grain_powder_nm"] * (1.0 + 0.15 * sig((850.0 - 870.0) / 20.0))
    z -= w["gamma_g"] * math.log(grain_nm / grain_ref)
    z += body_v
    z_as = z
    dz, r_br, r_n = anneal_effects(rt["anneal"], w, lot)
    z += dz
    rho = density(rt, w) + rho_eps
    por = max(0.0, 1.0 - rho / cal["density"]["rho_s"])
    por_ref = max(0.0, 1.0 - cal["rho_model"]["E"] / cal["density"]["rho_s"])
    por_factor = (1.0 - w["kappa_por"] * por) / (1.0 - w["kappa_por"] * por_ref)
    f_dec = sig((rt["peak_c"] + w["dT_contact"] * math.sqrt(rt["ramp"] / 100.0) - w["T_dec"]) / 8.0)
    h_ceil = w["H_ceil"]
    hci_as = h_ceil * sig(z_as) * (1 - cal["dH_dec"] * f_dec) * por_factor
    hci = h_ceil * sig(z) * (1 - cal["dH_dec"] * f_dec) * por_factor
    br_as = (cal["B_iso"] * rho / cal["density"]["rho_s"]
             * (1 - cal["a_br"] * math.exp(-hci_as / cal["Hm"])) * (1 - cal["dBr_dec"] * f_dec)
             * math.exp(-w["beta_O"] * o))
    br = br_as * r_br
    n = cal["n_as"] * lot["n_lot"] * r_n
    return {"hci_kOe": hci, "br_kGs": br, "n": n, "bhmax_MGOe": bhmax(br, hci, n),
            "squareness": squareness_from_n(n), "density_g_cm3": rho, "porosity": por,
            "z": z, "h_residual": h, "oxidation": o, "f_dec": f_dec, "grain_nm": grain_nm}


# ------------------------------------------------------------------ random effects and observation

def batch_effect(w, seed, lot_id, preparation_id):
    s = w["sigma_lnh_batch"]
    return float(rng_for(seed, f"batch:{lot_id}:{preparation_id}").normal(-s * s / 2, s)) if s > 0 else 0.0


def body_effects(w, seed, specimen_id):
    r = rng_for(seed, f"body:{specimen_id}")
    return float(r.normal(0, w["sigma_z_body"])), float(r.normal(0, w["sigma_rho_body"]))


def observe_curve(state, w, seed, identity):
    """One closed-circuit curve on one piece: Br, Hci and loop-shape repeatability."""
    r = rng_for(seed, f"meas:demag:{identity}")
    noise = w["cal"]["noise"]
    br = state["br_kGs"] + r.normal(0, noise["br_sd_kGs"])
    hci = state["hci_kOe"] * (1 + r.normal(0, noise["hci_cv"]))
    n = state["n"] * (1 + r.normal(0, noise["n_cv"]))
    return {"br_kGs": float(br), "hci_kOe": float(hci), "n": float(n), "bhmax_MGOe": bhmax(br, hci, n),
            "squareness": squareness_from_n(n)}


def observe_screen(state, w, seed, identity):
    r = rng_for(seed, f"meas:screen:{identity}")
    return {"hci_kOe": float(state["hci_kOe"] * (1 + r.normal(0, w["cal"]["noise"]["screen_cv"])))}


def boundary_class(state, w):
    """Categorical SEM boundary-phase distribution; saturates at half the 10-min removal."""
    removal = (1 - state["h_residual"]) / (1 - math.exp(-w["kappa"]))
    if removal < 0.5:
        return 0
    return 1 if state["schedule"] == "on_heating" and not state["high_temperature_anneal"] else 2


BOUNDARY_DESCRIPTIONS = (
    ("pooled", "boundary-phase contrast pooled at triple junctions; most grain edges appear bare"),
    ("wetted_with_junction_pooling", "boundary-phase contrast along selected grain edges with pooling at junctions"),
    ("continuous_network", "continuous boundary-phase contrast along most grain edges at this resolution"),
)


# ------------------------------------------------------------------ anchor inversion

def calibrate_world(anchor, dens, w, noise):
    """Invert the model at the released anchors so every world reproduces them.

    anchor: {"C": {"hci","br"}, "D", "E", "A", "E900", "E900_520", "n": {"E","E900","E900_520"},
    "rho": {"D","E"}}; values may be jittered within measurement repeatability. Hidden
    parameters touching the anchor recipes (porosity, grain, decomposition, liquid terms)
    are divided out, so hidden choices move only directions no released record constrains.
    """
    stub = {**w, "cal": {"density": dens, "drho_E": anchor["rho"]["D"] - anchor["rho"]["E"]}}
    rho_on = density_on_heating(850.0, 10.0, 600.0, 50.0, dens)
    rho_model = {"C": rho_on, "D": rho_on, "E": rho_on - stub["cal"]["drho_E"],
                 "A": density_on_heating(950.0, 100.0, 600.0, 50.0, dens)}
    rho_s = dens["rho_s"]
    por = {k: 1.0 - v / rho_s for k, v in rho_model.items()}
    por_factor = {k: (1 - w["kappa_por"] * por[k]) / (1 - w["kappa_por"] * por["E"]) for k in por}

    def fdec(peak, ramp):
        return sig((peak + w["dT_contact"] * math.sqrt(ramp / 100.0) - w["T_dec"]) / 8.0)

    f = {"C": fdec(850, 10), "D": fdec(850, 10), "E": fdec(850, 10), "A": fdec(950, 100)}

    def grain(peak):
        return w["grain_powder_nm"] * (1.0 + 0.15 * sig((peak - 870.0) / 20.0))

    zgrain_a = -w["gamma_g"] * math.log(grain(950.0) / grain(850.0))
    zliq_a = -w["d_liq"] * ((1 - sig((950.0 - w["T_liq"]) / 15.0)) - (1 - sig((850.0 - w["T_liq"]) / 15.0)))
    hc = w["H_ceil"]
    d_h = 0.0
    for _ in range(4):  # fixed point: z_C depends weakly on d_h through f_dec(C)
        zc = logit(anchor["C"]["hci"] / (hc * (1 - d_h * f["C"]) * por_factor["C"]))
        base_a = hc * sig(zc + zgrain_a + zliq_a) * por_factor["A"]
        d_h = (1 - anchor["A"]["hci"] / base_a) / f["A"]
    z = {k: logit(anchor[k]["hci"] / (hc * (1 - d_h * f[k]) * por_factor[k])) for k in ("C", "D", "E")}
    o_anchor = {"C": 0.0, "D": 1.0, "E": 1.0}
    y = {k: anchor[k]["br"] / (rho_model[k] / rho_s) / math.exp(-w["beta_O"] * o_anchor[k]) for k in ("C", "D", "E")}
    h = {k: anchor[k]["hci"] for k in ("C", "D", "E")}

    def ratio(hm):
        e = {k: math.exp(-h[k] / hm) for k in h}
        return (e["D"] - e["E"]) / (e["C"] - e["E"]) - (y["E"] - y["D"]) / (y["E"] - y["C"])

    lo, hi = 0.2, 20.0
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if ratio(lo) * ratio(mid) <= 0:
            hi = mid
        else:
            lo = mid
    hm = 0.5 * (lo + hi)
    e = {k: math.exp(-h[k] / hm) for k in h}
    ba = (y["E"] - y["C"]) / (e["C"] - e["E"])
    b_iso = y["E"] + ba * e["E"]
    a_br = ba / b_iso
    br_a_nodec = b_iso * rho_model["A"] / rho_s * (1 - a_br * math.exp(-anchor["A"]["hci"] / hm))
    d_br = (1 - anchor["A"]["br"] / br_a_nodec) / f["A"]
    z900 = logit(anchor["E900"]["hci"] / (hc * (1 - d_h * f["E"]) * por_factor["E"]))
    z2 = logit(anchor["E900_520"]["hci"] / (hc * (1 - d_h * f["E"]) * por_factor["E"]))
    return {"H_ceil": hc, "zC": z["C"], "dCD": z["D"] - z["C"], "dDE": z["E"] - z["D"],
            "A1": z900 - z["E"], "A2": z2 - z900, "dH_dec": d_h, "dBr_dec": d_br,
            "B_iso": b_iso, "a_br": a_br, "Hm": hm,
            "r1_900": anchor["E900"]["br"] / anchor["E"]["br"],
            "r2_520": anchor["E900_520"]["br"] / anchor["E900"]["br"],
            "n_as": anchor["n"]["E"], "n1_ratio": anchor["n"]["E900"] / anchor["n"]["E"],
            "n2_ratio": anchor["n"]["E900_520"] / anchor["n"]["E900"],
            "density": dens, "drho_E": stub["cal"]["drho_E"], "rho_model": rho_model,
            "noise": noise}


# ------------------------------------------------------------------ owner world configuration

def world_model(world_config):
    """Validate an owner world and return hidden parameters with the inverted anchors."""
    if not isinstance(world_config, dict) or world_config.get("family") != FAMILY:
        raise ValueError("magnetic workflow requires an explicit ndfeb_magnetic_workflow_v1 world")
    unknown = set(world_config) - WORLD_KEYS
    if unknown:
        raise ValueError(f"unknown world keys {sorted(unknown)}")
    calibration = world_config["calibration"]
    anchors, dens, noise = calibration["anchors"], calibration["density"], calibration["noise"]
    hidden = world_config["hidden"]
    if set(hidden) != set(HIDDEN_KEYS):
        raise ValueError(f"hidden parameters must be exactly {sorted(HIDDEN_KEYS)}")
    for name, value in [*hidden.items(), *dens.items()]:
        _number(value, name)
    for key in ("hci_cv", "br_sd_kGs", "n_cv", "screen_cv"):
        _number(noise[key], key, 0, 1)
    lots = world_config["lots"]
    if not isinstance(lots, dict) or not lots:
        raise ValueError("world must declare at least one powder lot")
    for lot_id, lot in lots.items():
        if set(lot) != set(LOT_KEYS):
            raise ValueError(f"lot {lot_id!r} requires exactly {list(LOT_KEYS)}")
        for name, value in lot.items():
            _number(value, f"{lot_id}.{name}", 0)
    w = {k: float(v) for k, v in hidden.items()}
    w["cal"] = calibrate_world(anchors, {k: float(v) for k, v in dens.items()}, w, noise)
    return w


def _degassing(conditions, where):
    if not isinstance(conditions, dict):
        raise ValueError(f"{where}: preparation requires a conditions object")
    method = conditions.get("method")
    if method not in DEGAS_METHODS:
        raise ValueError(f"{where}: preparation method must be one of {list(DEGAS_METHODS)}")
    allowed = {"method", "temperature_c", "hold_time_s"}
    unknown = set(conditions) - allowed
    if unknown:
        raise ValueError(f"{where}: unsupported preparation controls {sorted(unknown)}; use {sorted(allowed)}")
    if method == "none":
        if "temperature_c" in conditions or conditions.get("hold_time_s", 0) != 0:
            raise ValueError(f"{where}: method none declares no degassing temperature or hold")
        return {"method": "none", "temperature_c": None, "hold_time_s": 0.0}
    low, high = SUPPORT_ENVELOPE["degassing_temperature_c"]
    temperature = _number(conditions.get("temperature_c"), f"{where}: degassing temperature_c", low, high)
    low, high = SUPPORT_ENVELOPE["degassing_hold_time_s"]
    hold = _number(conditions.get("hold_time_s"), f"{where}: degassing hold_time_s", low, high)
    if hold <= 0:
        raise ValueError(f"{where}: vacuum_degassing requires a positive hold_time_s; use method none for no degassing")
    return {"method": "vacuum_degassing", "temperature_c": temperature, "hold_time_s": hold}


def _in(value, allowed):
    return any(abs(float(value) - float(a)) < 1e-9 for a in allowed)


def _domain_check(domain, key, value, where):
    if domain is None or key not in domain:
        return
    if not _in(value, domain[key]):
        raise ValueError(f"{where}: {key} {value:g} is outside this task's declared control set-points "
                         f"{[float(v) for v in domain[key]]}")


def _check_degassing_domain(domain, executed, where):
    if domain is None or "degassing_set_points" not in domain:
        return
    for point in domain["degassing_set_points"]:
        if point.get("method") == executed["method"] and (
                executed["method"] == "none"
                or (abs(point["temperature_c"] - executed["temperature_c"]) < 1e-9
                    and abs(point["hold_time_s"] - executed["hold_time_s"]) < 1e-9)):
            return
    raise ValueError(f"{where}: degassing {executed} is outside this task's declared degassing set-points")


def _manufacture_controls(condition, sid, domain):
    unknown = set(condition) - MANUFACTURE_KEYS
    if unknown:
        raise ValueError(f"{sid}: unsupported manufacture controls {sorted(unknown)}; "
                         f"use {sorted(MANUFACTURE_KEYS - {'operation', 'output_stage'})}")
    controls = {}
    for key in ("temperature_c", "heating_rate_c_min", "hold_time_s", "pressure_mpa"):
        if key not in condition:
            raise ValueError(f"{sid}: manufacture requires explicit {key}")
        low, high = SUPPORT_ENVELOPE[key]
        controls[key] = _number(condition[key], f"{sid}: {key}", low, high)
        _domain_check(domain, key, controls[key], sid)
    schedule = condition.get("pressure_schedule")
    if schedule not in SCHEDULES:
        raise ValueError(f"{sid}: pressure_schedule must be one of {list(SCHEDULES)}")
    if domain is not None and "pressure_schedule" in domain and schedule not in domain["pressure_schedule"]:
        raise ValueError(f"{sid}: pressure_schedule {schedule} is outside this task's declared schedules")
    controls["pressure_schedule"] = schedule
    if schedule == "on_cooling":
        low, high = SUPPORT_ENVELOPE["pressure_full_at_c"]
        full = _number(condition.get("pressure_full_at_c"), f"{sid}: pressure_full_at_c", low, high)
        if full > controls["temperature_c"]:
            raise ValueError(f"{sid}: pressure_full_at_c must not exceed the peak temperature_c")
        _domain_check(domain, "pressure_full_at_c", full, sid)
        controls["pressure_full_at_c"] = full
    elif "pressure_full_at_c" in condition:
        raise ValueError(f"{sid}: pressure_full_at_c applies only to pressure_schedule on_cooling")
    low, high = SUPPORT_ENVELOPE["mass_g"]
    controls["mass_g"] = _number(condition.get("mass_g"), f"{sid}: mass_g", low, high)
    return controls


def _anneal_controls(condition, sid, input_stage, output_stage, domain):
    extra = set(condition) - {"anneal_steps", "mass_g", "measurement_context", "operation",
                              "output_stage", "input_stage", "process_stage", "cooling_mode"}
    if extra:
        raise ValueError(f"{sid}: anneal controls belong in canonical anneal_steps; unsupported {sorted(extra)}")
    if "anneal_steps" not in condition:
        raise ValueError(f"{sid}: submit explicit canonical anneal_steps (stage, temperature_c, "
                         "hold_time_s, heating_rate_c_min for each step)")
    validate_anneal_condition(condition, input_stage=input_stage, output_stage=output_stage)
    steps = _resolved_anneal_steps(condition, {"anneal_heating_rate_c_min": 10.0}, input_stage,
                                   output_stage, 5.0)
    for step in steps:
        low, high = SUPPORT_ENVELOPE["anneal_temperature_c"]
        _number(step["temperature_c"], f"{sid}: anneal temperature_c", low, high)
        low, high = SUPPORT_ENVELOPE["anneal_hold_time_s"]
        _number(step["hold_time_s"], f"{sid}: anneal hold_time_s", low, high)
        key = ("anneal_high_temperature_c" if step["temperature_c"] >= HIGH_STEP_MIN_C
               else "anneal_low_temperature_c")
        _domain_check(domain, key, step["temperature_c"], sid)
        _domain_check(domain, "anneal_hold_time_s", step["hold_time_s"], sid)
        _domain_check(domain, "anneal_heating_rate_c_min", step["heating_rate_c_min"], sid)
    return steps


def _context(condition, sid):
    context = condition.get("measurement_context", {})
    if not isinstance(context, dict) or set(context) - CONTEXT_KEYS:
        raise ValueError(f"{sid}: measurement_context only accepts {sorted(CONTEXT_KEYS)}")
    piece = context.get("piece_id", "1")
    if not isinstance(piece, str) or not piece.strip() or len(piece) > 64:
        raise ValueError(f"{sid}: measurement_context.piece_id must be a nonempty identifier")
    return context, piece


def validate_magnetic_request_controls(request, domain=None):
    """World-free validation of NEW magnetic-family request controls; raises ValueError.

    ``domain`` is the task's declared control set-points (packet text), if any. No
    fit, simulation, ledger mutation or private-world lookup happens here.
    """
    if domain is not None:
        if not isinstance(domain, dict) or set(domain) - DOMAIN_KEYS:
            raise ValueError("declared magnetic domain has unknown keys")
    operation = request.get("operation", "manufacture")
    if operation not in {"manufacture", "anneal", "measure"}:
        raise ValueError("unsupported workflow operation")
    misplaced = sorted(set(request) & (CONTEXT_KEYS | {"measurement_context", "consumed_mass_g",
                                                      "destructive", "specimen_available"}))
    if misplaced:
        raise ValueError(f"{', '.join(misplaced)} belong on each specimen (material controls) or in "
                         "specimen.conditions.measurement_context (sampling), not on the request")
    process = {"anneal_steps", "temperature_c", "hold_time_s", "heating_rate_c_min", "pressure_mpa",
               "pressure_schedule", "pressure_full_at_c", "steps"}
    if set(request) & process:
        raise ValueError("process controls belong in each specimen.conditions")
    preparations = request.get("preparations", [])
    if operation != "manufacture" and preparations:
        raise ValueError("preparations are declared only with new manufacture")
    for preparation in preparations:
        executed = _degassing(preparation.get("conditions"), str(preparation.get("preparation_id")))
        _check_degassing_domain(domain, executed, str(preparation.get("preparation_id")))
    for specimen in request.get("specimens", []):
        sid = str(specimen.get("specimen_id"))
        condition = specimen.get("conditions")
        if not isinstance(condition, dict):
            raise ValueError(f"{sid}: each specimen requires a conditions object")
        if set(specimen) & CONTEXT_KEYS or set(condition) & (CONTEXT_KEYS - {"measurement_context"}):
            raise ValueError(f"{sid}: sampling choices belong in specimen.conditions.measurement_context")
        if set(condition) & {"consumed_mass_g", "destructive", "specimen_available"}:
            raise ValueError(f"{sid}: material controls belong directly on the specimen, not its conditions")
        if condition.get("operation", operation) != operation:
            raise ValueError(f"{sid}: specimen conditions.operation conflicts with the requested operation")
        selection = specimen.get("measurements", request.get("measurements"))
        if not isinstance(selection, list) or not selection:
            raise ValueError(f"{sid}: magnetic worlds require an explicit nonempty measurements selection")
        if len(selection) != len(set(selection)) or set(selection) - SUPPORTED:
            raise ValueError(f"{sid}: unsupported or duplicated measurements "
                             f"{sorted(set(selection) - SUPPORTED)}; supported {sorted(SUPPORTED)}")
        if "sps_log" in selection and operation != "manufacture":
            raise ValueError(f"{sid}: an anneal or repeat measurement cannot produce a new SPS trace")
        _context(condition, sid)
        if operation == "manufacture":
            _manufacture_controls(condition, sid, domain)
        elif operation == "anneal":
            input_stage = request.get("input_stage", specimen.get("input_stage", "as_sintered"))
            _anneal_controls(condition, sid, input_stage, request.get("output_stage"), domain)
        else:
            unknown = set(condition) - MEASURE_KEYS
            if unknown:
                raise ValueError(f"{sid}: a repeat measurement accepts only mass_g and measurement_context, "
                                 f"not {sorted(unknown)}")


# ------------------------------------------------------------------ history replay

def _replay(history, sid):
    """Rebuild the executed route from bound released processing history."""
    if not isinstance(history, list) or not history:
        raise ValueError(f"{sid}: existing-specimen operation needs bound prior_processing_conditions")
    first = history[0]
    if first.get("operation") != "manufacture" or not isinstance(first.get("executed_preparation"), dict):
        raise ValueError(f"{sid}: processing history must start with a magnetic-family manufacture record")
    prep = first["executed_preparation"]
    degas_s = float(prep["hold_time_s"]) if prep["method"] == "vacuum_degassing" else 0.0
    route = {"degas_c": float(prep["temperature_c"]) if degas_s > 0 else 600.0, "degas_s": degas_s,
             "peak_c": float(first["temperature_c"]), "ramp": float(first["heating_rate_c_min"]),
             "hold_s": float(first["hold_time_s"]), "pressure_mpa": float(first["pressure_mpa"]),
             "schedule": first["pressure_schedule"],
             "t_full_c": float(first.get("pressure_full_at_c") or 750.0), "anneal": []}
    stage = first.get("output_stage", "as_sintered")
    for index, previous in enumerate(history[1:], start=1):
        if previous.get("operation") != "anneal" or not isinstance(previous.get("anneal_steps"), list):
            raise ValueError(f"{sid}: history entry {index} is not an executed anneal record")
        for step in previous["anneal_steps"]:
            route["anneal"].append((float(step["temperature_c"]), float(step["hold_time_s"])))
        stage = previous.get("output_stage", stage)
    return route, stage


# ------------------------------------------------------------------ instruments

def _sps_trace(route, condition, state, measurement, dens):
    """Constructed schedule-aware SPS trace; not a calibrated displacement kinetic model."""
    peak, ramp, hold = route["peak_c"], route["ramp"], route["hold_s"]
    pressure = route["pressure_mpa"]
    ramp_s, cool_s = (peak - 25) / ramp * 60, (peak - 25) / SPS_COOLING_C_MIN * 60
    times = np.unique(np.concatenate((np.linspace(0, ramp_s, 61), np.linspace(ramp_s, ramp_s + hold, 21),
                                      np.linspace(ramp_s + hold, ramp_s + hold + cool_s, 61))))
    q = dens["Q_kj_mol"]
    full_dose = thermal_dose(peak, ramp, hold, q, cooling_rate_c_min=SPS_COOLING_C_MIN)
    dwell_dose = thermal_dose(peak, ramp, hold, q)
    temps, doses, pressures = [], [], []
    for t in times:
        if t <= ramp_s:
            temp = 25 + t * ramp / 60
            dose = thermal_dose(float(temp), ramp, 0, q)
            load = (pressure * (temp - 25) / (peak - 25) if route["schedule"] == "on_heating" else 0.0)
        elif t <= ramp_s + hold:
            temp = peak
            dose = thermal_dose(peak, ramp, float(t - ramp_s), q)
            load = 0.0 if route["schedule"] == "on_cooling" else pressure
        else:
            temp = max(25.0, peak - (t - ramp_s - hold) * SPS_COOLING_C_MIN / 60)
            dose = dwell_dose + (full_dose - dwell_dose) * (peak - temp) / (peak - 25)
            if route["schedule"] == "on_cooling":
                span = max(peak - route["t_full_c"], 1e-9)
                load = pressure * min(1.0, (peak - temp) / span)
            else:
                load = pressure
        temps.append(float(temp))
        doses.append(float(dose))
        pressures.append(float(load))
    rho0 = dens["rho0"]
    rho_final = state["density_g_cm3"]
    rho = [rho0 + (rho_final - rho0) * d / doses[-1] for d in doses]
    mass = condition["mass_g"]
    diameter = _number(condition.get("diameter_mm", 10), "conditional diameter", 1, 50)
    area = math.pi * (diameter / 20) ** 2
    tooling = _number(measurement.get("tooling_displacement_mm_per_c", 0.001), "tooling coefficient", -0.01, 0.01)
    displacement = [10 * mass / area * (1 / rho0 - 1 / r) + tooling * (t - 25) for r, t in zip(rho, temps)]
    with tempfile.TemporaryDirectory(prefix="ndfeb-magnetic-sps-") as directory:
        path = Path(directory) / "constructed.csv"
        with path.open("w", newline="") as handle:
            writer = csv.writer(handle)
            writer.writerow(["time_s", "temperature_C", "pressure_MPa", "displacement_mm"])
            writer.writerows(zip(times.tolist(), temps, pressures, displacement))
        reduced = read_sps_csv(path)
    return {"time_s": times.tolist(), "temperature_c": temps, "pressure_mpa": pressures,
            "displacement_mm": displacement, "reduction": reduced,
            "pressure_schedule": route["schedule"], "method": "constructed_normalized_sensor_trace",
            "limits": ["Tooling term not independently removed", "Sensor temperature need not be powder temperature",
                       "Densification progress is a thermal-dose closure scaled to the delivered density",
                       "No SPS electrical energy or power measurement"]}


def _curve(state, w, seed, sid, stage, request_hash, piece):
    ident = f"{sid}:{stage}:{request_hash[:16]}:{piece}"
    obs = observe_curve(state, w, seed, ident)
    fields, polarization = demag_vertices(obs["br_kGs"], obs["hci_kOe"], obs["n"])
    record = {"specimen_id": sid, "piece_id": piece, "field_kOe": fields, "polarization_kGs": polarization,
              "units": {"field": "kOe", "polarization": "kGs", "energy_product": "MGOe"},
              "curve": "intrinsic_second_quadrant", "method": "closed_circuit_demagnetization_curve",
              "status": "constructed_vertices_not_instrument_export"}
    reduced = {r["quantity"]: r for r in demag_curve_observations([record])}
    for r in reduced.values():
        if r["status"] == "derived":
            r["status"] = "conditional_synthetic"
    raw = {"raw_piece_records": [record],
           "reduction": {q: r["value"] for q, r in reduced.items()},
           "method": "closed_circuit_demagnetization_curve",
           "measurement_assumptions": {
               "values": "apparent reported quantities; no demagnetizing, temperature or geometry correction",
               "units": "CGS (kOe, kGs, MGOe)", "piece": piece,
               "repeatability_basis": "within-body piece plus instrument repeatability"}}
    return reduced, raw


def _icp(prep_id, executed, lot, w, world_config, seed, request_hash):
    settings = world_config.get("icp", {})
    base = _number(settings.get("oxygen_base_wt_pct", 0.25), "icp oxygen base", 0, 5)
    per_index = _number(settings.get("oxygen_per_index_wt_pct", 0.05), "icp oxygen per index", 0, 5)
    tre = _number(settings.get("tre_wt_pct", 30.5), "icp TRE", 0, 100)
    t_dg = executed["hold_time_s"]
    o = lot["o_lot"] * (t_dg / 600.0) * arrhenius(w["E_ox"], executed["temperature_c"]) if t_dg > 0 else 0.0
    r = rng_for(seed, f"icp:{prep_id}:{request_hash[:16]}")
    oxygen = base + per_index * o + float(r.normal(0, 0.15))
    total = tre + float(r.normal(0, 0.3))
    return {"value": {"tre_wt_pct": total, "oxygen_wt_pct_by_difference": oxygen,
                      "hydrogen": {"value": None, "status": "unavailable",
                                   "reason": "ICP-OES does not measure hydrogen"}},
            "unit": "mixed", "method": "icp_oes_powder_aliquot",
            "uncertainty": {"tre_wt_pct_sd": 0.3, "oxygen_wt_pct_by_difference_sd": 0.15},
            "measurement_population": "preparation_batch_powder", "statistical_unit": "preparation",
            "limits": ["Oxygen is reported by difference with a large uncertainty",
                       "Hydrogen is not measured by ICP-OES"]}


# ------------------------------------------------------------------ provider entry point

def simulate_magnetic_workflow(request, world_config, seed):
    """Native response entry point for degassing, manufacture, anneal and measure."""
    if world_config.get("family") != FAMILY or request.get("origin") != "synthetic":
        raise ValueError("magnetic workflow requires an explicit synthetic family and request")
    w = world_model(world_config)
    domain = world_config.get("domain")
    validate_magnetic_request_controls(request, domain)
    operation = request.get("operation", "manufacture")
    lot_id = request["lot_id"]
    if lot_id not in world_config["lots"]:
        raise ValueError(f"unknown powder lot {lot_id!r} in this world")
    lot = {k: float(v) for k, v in world_config["lots"][lot_id].items()}
    measurement = world_config.get("measurement", {})
    sem = world_config.get("sem", {})
    preseeded = world_config.get("preseeded_batches", {})
    request_hash = hashlib.sha256(_canonical(request)).hexdigest()
    preparation_outcomes, executed_preparations = {}, {}
    for preparation in request.get("preparations", []):
        pid = preparation["preparation_id"]
        requested = _degassing(preparation["conditions"], pid)
        if pid in preseeded:
            record = preseeded[pid]
            if record["lot_id"] != lot_id:
                raise ValueError(f"{pid}: pre-seeded batch belongs to another lot")
            executed = _degassing({k: record[k] for k in ("method", "temperature_c", "hold_time_s")
                                   if k in record}, pid)
        else:
            executed = requested
        executed_preparations[pid] = executed
        outcome = {"executed": True, "conditions": executed, "requested_conditions": preparation["conditions"],
                   "origin": "synthetic", "status": "conditional_execution_not_physical_preparation"}
        if executed != requested:
            outcome["execution_deviation"] = "pre-seeded batch; recorded degassing executed, not the declared conditions"
        preparation_outcomes[pid] = outcome
    observations, delivered, outcomes = [], {}, {}
    for specimen in request["specimens"]:
        sid, pid, cycle = (specimen[k] for k in ("specimen_id", "preparation_id", "cycle_id"))
        condition = copy.deepcopy(specimen["conditions"])
        context, piece = _context(condition, sid)
        selection = specimen.get("measurements", request.get("measurements"))
        if operation == "manufacture":
            if "prior_processing_conditions" in specimen:
                raise ValueError(f"{sid}: manufacture cannot overwrite an existing specimen history")
            if pid in executed_preparations:
                executed = executed_preparations[pid]
            elif pid in preseeded:
                record = preseeded[pid]
                if record["lot_id"] != lot_id:
                    raise ValueError(f"{pid}: pre-seeded batch belongs to another lot")
                executed = _degassing({k: record[k] for k in ("method", "temperature_c", "hold_time_s")
                                       if k in record}, pid)
            else:
                raise ValueError(f"{sid}: declare preparation {pid!r} with its degassing conditions in "
                                 "request.preparations (identical to its first declaration)")
            controls = _manufacture_controls(condition, sid, domain)
            route = {"degas_c": executed["temperature_c"] if executed["hold_time_s"] > 0 else 600.0,
                     "degas_s": executed["hold_time_s"], "peak_c": controls["temperature_c"],
                     "ramp": controls["heating_rate_c_min"], "hold_s": controls["hold_time_s"],
                     "pressure_mpa": controls["pressure_mpa"], "schedule": controls["pressure_schedule"],
                     "t_full_c": controls.get("pressure_full_at_c", 750.0), "anneal": []}
            stage = "as_sintered"
            if request.get("output_stage", stage) != stage:
                raise ValueError(f"{sid}: manufacture produces as_sintered bodies")
            # The SPS cooling rate is an owner model constant derived from a display trace; it is
            # not echoed as an executed readback (leakage rule L1/L6).
            actual = {**condition, **controls, "executed_preparation": {"preparation_id": pid, **executed}}
        else:
            route, prior_stage = _replay(specimen.get("prior_processing_conditions"), sid)
            if request.get("input_stage", prior_stage) != prior_stage:
                raise ValueError("request.input_stage conflicts with executed prior history")
            if specimen.get("input_stage", prior_stage) != prior_stage:
                raise ValueError("specimen.input_stage conflicts with executed prior history")
            actual = dict(condition)
            if operation == "anneal":
                steps = _anneal_controls(condition, sid, prior_stage, request.get("output_stage"), domain)
                route["anneal"].extend((float(s["temperature_c"]), float(s["hold_time_s"])) for s in steps)
                stage = request["output_stage"]
                public = ("stage", "temperature_c", "hold_time_s", "heating_rate_c_min", "pressure_mpa",
                          "cooling_rate_c_min")
                actual["anneal_steps"] = [{k: s[k] for k in public} for s in steps]
                actual["execution_control_status"] = "canonical_controls_from_executed_steps"
            else:
                stage = prior_stage
                if request.get("output_stage", stage) != stage:
                    raise ValueError("a measurement cannot change the processing stage")
        actual.update(operation=operation, output_stage=stage)
        u = batch_effect(w, seed, lot_id, pid)
        v, e = body_effects(w, seed, sid)
        state = latent_state(route, w, lot, batch_u=u, body_v=v, rho_eps=e)
        state["schedule"] = route["schedule"]
        state["high_temperature_anneal"] = any(t >= HIGH_STEP_MIN_C for t, _ in route["anneal"])
        identity = {"specimen_id": sid, "lot_id": lot_id, "preparation_id": pid, "cycle_id": cycle,
                    "origin": "synthetic", "process_stage": stage}
        records = {}
        if "density_g_cm3" in selection:
            mass = _number(condition.get("mass_g", specimen.get("remaining_mass_g")),
                           f"{sid}: conditional specimen mass", 0.01, 25)
            records["density_g_cm3"] = archimedes_response(state["density_g_cm3"], mass, measurement,
                                                           porosity_fraction=state["porosity"])
        if set(selection) & SEM_SELECTION:
            coarse = _number(sem.get("coarse_to_fine_ratio", 1.8), "sem coarse ratio", 1, 20)
            fraction = _number(sem.get("coarse_region_area_fraction", 0.10), "sem coarse fraction", 0, 1)
            sem_state = {"fine_region_mean_grain_size_nm": state["grain_nm"],
                         "coarse_region_mean_grain_size_nm": state["grain_nm"] * coarse,
                         "coarse_region_area_fraction": fraction, "porosity_fraction": state["porosity"]}
            sampling = {k: v for k, v in context.items() if k != "piece_id"}
            descriptors, micro = microscopy_response(sid, sem_state, {**measurement, **sampling}, seed, stage)
            label, text = BOUNDARY_DESCRIPTIONS[boundary_class(state, w)]
            micro["boundary_phase_distribution"] = {
                "class": label, "description": text, "status": "constructed_qualitative_field_description",
                "limits": ["SEM cannot resolve a 1-2 nm grain-boundary film",
                           "Contrast does not identify a chemical phase or a causal mechanism",
                           "No magnetic-property inference follows from this descriptor"]}
            raw_fields = micro["raw_field_records"]
            counts = [len(r["grain_sizes_nm"]) for r in raw_fields]
            actual["measurement_context"] = {
                **{k: v for k, v in context.items() if k == "piece_id"},
                "field_count": len(raw_fields),
                "features_per_field": counts[0] if len(set(counts)) == 1 else None,
                "field_set_id": str(sampling.get("field_set_id", measurement.get("field_set_id", "default"))),
                "selection": micro["selection"],
                "coarse_threshold_nm": micro["measurement_assumptions"]["coarse_threshold_nm"]}
            records.update(descriptors)
            records["microstructure"] = {"value": micro, "unit": "mixed", "method": micro["method"]}
        if set(selection) & CURVE_SELECTION:
            reduced, raw = _curve(state, w, seed, sid, stage, request_hash, piece)
            for quantity in CURVE_SCALARS:
                records[quantity] = reduced[quantity]
            records["demagnetization_curve"] = {"value": raw, "unit": "mixed", "method": raw["method"]}
        if "hci_screen_kOe" in selection:
            screen = observe_screen(state, w, seed, f"{sid}:{stage}:{request_hash[:16]}:{piece}")
            records["hci_screen_kOe"] = {
                "value": screen["hci_kOe"], "unit": "kOe", "method": "open_circuit_hci_screen",
                "uncertainty": None, "measurement_statistic": "single_piece",
                "limits": ["Open-circuit screen returns intrinsic coercivity only; no Br, loop shape or (BH)max",
                           "Apparent value without demagnetizing correction"]}
        if "powder_icp_oes" in selection:
            if operation == "manufacture":
                executed_prep = actual["executed_preparation"]
            else:
                executed_prep = specimen["prior_processing_conditions"][0]["executed_preparation"]
            records["powder_icp_oes"] = _icp(pid, executed_prep, lot, w, world_config, seed, request_hash)
        if "sps_log" in selection:
            records["sps_log"] = {"value": _sps_trace(route, actual, state, measurement, w["cal"]["density"]),
                                  "unit": "mixed"}
        delivered[sid] = {**actual, **identity, "delivery_status": "declared_conditional_execution"}
        for quantity in selection:
            rec = records.get(quantity, {
                "value": None, "unit": SCALARS.get(quantity, "mixed"), "status": "unavailable",
                "reason": "SEM/EDS cannot resolve the grain-boundary film chemistry; no numerical response"})
            observations.append({**rec, **identity, "observation_id": f"{request_hash[:16]}:{sid}:{quantity}",
                                 "quantity": quantity, "status": rec.get("status", "conditional_synthetic"),
                                 "uncertainty": rec.get("uncertainty"),
                                 "evidence_scope": "conditional_computation_not_RPI_measurement"})
        consumed = _number(specimen.get("consumed_mass_g", 0), "consumed mass", 0)
        available_mass = condition.get("mass_g", specimen.get("remaining_mass_g"))
        if available_mass is not None:
            available_mass = _number(available_mass, "available mass", 0, 25)
            if consumed > available_mass:
                raise ValueError("declared consumption exceeds conditional specimen mass")
        remaining = None if available_mass is None else available_mass - consumed
        outcomes[sid] = {"executed": True, "stage": stage, "consumed_mass_g": consumed,
                         "destructive": specimen.get("destructive", False), "remaining_mass_g": remaining,
                         "specimen_available": specimen.get("specimen_available", remaining != 0),
                         "operation": operation, "preparation_execution_status": "conditional"}
    return {"delivery_id": "conditional-" + request_hash[:20], "origin": "synthetic", "complete": True,
            "observations": observations, "delivered_conditions": delivered,
            "specimen_outcomes": outcomes, "preparation_outcomes": preparation_outcomes,
            "manufactured_specimen_ids": list(delivered) if operation == "manufacture" else [],
            "simulation_accounting": {"operation": operation,
                                      "new_manufactured_count": len(delivered) if operation == "manufacture" else 0,
                                      "status": "conditional_not_physical_throughput"},
            "provenance": {"evidence_class": "conditional_synthetic", "model_version": FAMILY,
                           "physical_execution": False,
                           "request_world_seed_sha256": hashlib.sha256(_canonical(
                               {"request": request, "world": world_config, "seed": seed})).hexdigest()}}
